export { descriptionId, view } from "../select";
export type { SelectAttributes, ViewConfig } from "../select";

export {
  shadcnSelectChevronClassName,
  shadcnSelectClassName,
  shadcnSelectDescriptionClassName,
  shadcnSelectLabelClassName,
  shadcnSelectWrapperClassName,
} from "./view";

export {
  chevronClassName as shadcnSelectChevronClassName,
  descriptionClassName as shadcnSelectDescriptionClassName,
  labelClassName as shadcnSelectLabelClassName,
  selectClassName as shadcnSelectClassName,
  selectWrapperClassName as shadcnSelectWrapperClassName,
} from "../select/view";

import { describe, expect, test } from "vitest";

import * as Select from "./index";

describe("shadcn Select registry view", () => {
  test("reuses the Foldkit Select view contract", () => {
    expect(Select.view).toBeTypeOf("function");
    expect(Select.descriptionId).toBeTypeOf("function");
    expect(Select.shadcnSelectClassName).toContain("rounded");
  });
});
